}

async function loadOrders(request) {
  try {
    const response = await request();
    if (!response.ok) return { ok: false, error: "http" };
    return { ok: true, orders: await response.json() };
  } catch { return { ok: false, error: "network" }; }
}

async function loadOrders(request) {
  try {
    const response = await request();
    if (!response.ok) return { ok: false, error: "http" };
    const orders = await response.json();
    if (!Array.isArray(orders) || !orders.every(order => order && Number.isInteger(order.id) && Number.isInteger(order.totalCents) && order.totalCents >= 0)) return { ok: false, error: "shape" };
    return { ok: true, orders };
  } catch { return { ok: false, error: "network" }; }
}

